 1	import { NextResponse } from 'next/server';
 2	import { createSession } from '@/lib/session';
 3	
 4	export const runtime = 'nodejs';
 5	
 6	// Native <form method="post"> target, so starting works without client JS. Redirects to /s/<id> (or back with ?error=).
 7	export async function POST(req: Request) {
 8	  const form = await req.formData().catch(() => null);
 9	  const prompt = String(form?.get('prompt') ?? '').trim();
10	  const back = (error: string) => NextResponse.redirect(new URL(`/?error=${error}`, req.url), 303);
11	  if (prompt.length < 4) return back('short');
12	  if (prompt.length > 1000) return back('long');
13	  try {
14	    const id = await createSession(prompt);
15	    return NextResponse.redirect(new URL(`/s/${id}`, req.url), 303);
16	  } catch (e) {
17	    console.error('[step1] create session failed', e);
18	    return back('server');
19	  }
20	}
 1	import { NextResponse } from 'next/server';
 2	import { act, getState, InputError } from '@/lib/session';
 3	
 4	export const runtime = 'nodejs';
 5	
 6	type Ctx = { params: Promise<{ id: string }> };
 7	
 8	export async function GET(_req: Request, { params }: Ctx) {
 9	  const state = getState((await params).id);
10	  return state ? NextResponse.json(state) : NextResponse.json({ error: '세션을 찾을 수 없어요.' }, { status: 404 });
11	}
12	
13	// body: {action: 'answer', turnId, choices: string[], text} | {action: 'wrap' | 'more' | 'back' | 'finish'}
14	export async function POST(req: Request, { params }: Ctx) {
15	  const body = await req.json().catch(() => null);
16	  if (!body || typeof body !== 'object' || Array.isArray(body)) return NextResponse.json({ error: '요청 형식이 잘못됐어요.' }, { status: 400 });
17	  try {
18	    const state = await act((await params).id, body as Record<string, unknown>);
19	    return state ? NextResponse.json(state) : NextResponse.json({ error: '세션을 찾을 수 없어요.' }, { status: 404 });
20	  } catch (e) {
21	    if (e instanceof InputError) return NextResponse.json({ error: e.message }, { status: 400 });
22	    console.error('[step1] action failed', e);
23	    return NextResponse.json({ error: '처리하지 못했어요. 다시 시도해 주세요.' }, { status: 500 });
24	  }
25	}
