12	export default async function Home({ searchParams }: { searchParams: Promise<{ error?: string }> }) {
13	  const { error } = await searchParams;
14	  const sessions = listSessions();
15	  return (
16	    <div className="layout">
17	      <div className="layout__main">
18	        <div className="page-head">
19	          <div className="page-head__text">
20	            <h1>어떤 게임을 만들고 싶나요?</h1>
21	            <p className="page-head__desc">대충 적어도 돼요. 질문에 하나씩 답하면 게임 이름과 설명으로 정리해 드려요.</p>
22	          </div>
23	        </div>
24	        <StartForm error={error ? ERRORS[error] ?? ERRORS.server : undefined} />
25	      </div>
26	      <section className="panel layout__side" aria-labelledby="recent-h">
27	        <header className="panel__head"><h2 className="panel__title" id="recent-h">최근 세션</h2></header>
28	        <div className="panel__body">
29	          {sessions.length ? (
30	            <ul className="sessions">
31	              {sessions.map((s) => (
32	                <li key={s.id}>
33	                  <a className="sessions__link" href={`/s/${s.id}`}>{s.title ?? s.prompt}</a>
34	                  <p className="meta">{s.status === 'done' ? '정리 완료' : `질문 중, 답 ${s.answered}개`}</p>
35	                  <p className="meta"><time dateTime={s.created_at}>{when(s.created_at)}</time></p>
36	                </li>
37	              ))}
38	            </ul>
39	          ) : (
40	            <div className="empty"><p>아직 세션이 없어요. 왼쪽에 아이디어를 적고 시작해 보세요.</p></div>
41	          )}
42	        </div>
43	      </section>
44	    </div>
45	  );
46	}
