 2	import { useRef, useState } from 'react';
 3	import { Clock } from './icons';
 4	
 5	const EXAMPLES = [
 6	  '고양이가 우주 농장을 운영하는 느긋한 게임',
 7	  '좀비가 나오는 편의점에서 하룻밤 버티기',
 8	  '친구랑 폰 하나로 번갈아 하는 짧은 퍼즐 대결',
