12	// Plain form POST (works without JS); JS only fills examples, adds Ctrl/Cmd+Enter and the busy state.
13	export default function StartForm({ error }: { error?: string }) {
14	  const [prompt, setPrompt] = useState('');
15	  const [busy, setBusy] = useState(false);
16	  const ref = useRef<HTMLTextAreaElement>(null);
17	  return (
18	    <form className="start panel" action="/api/sessions" method="post" onSubmit={() => setBusy(true)} aria-busy={busy}>
19	      <div className="panel__body start__body">
20	        <div className="field">
21	          <label className="field__label" htmlFor="prompt">게임 아이디어</label>
22	          <textarea
23	            ref={ref} className="textarea start__input" id="prompt" name="prompt" rows={5} required minLength={4} maxLength={1000}
24	            placeholder="예: 고양이가 우주 농장을 운영하는 느긋한 게임" value={prompt} onChange={(e) => setPrompt(e.target.value)}
25	            aria-describedby={error ? 'prompt-help prompt-error' : 'prompt-help'} aria-invalid={error ? true : undefined}
26	            onKeyDown={(e) => { if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) e.currentTarget.form?.requestSubmit(); }}
27	          />
28	          <p className="field__help" id="prompt-help">한두 문장이면 충분해요. Ctrl+Enter로 바로 시작할 수 있어요.</p>
29	          {error && <p className="field__error" id="prompt-error">{error}</p>}
30	        </div>
31	        <div className="start__examples">
32	          <p className="meta" id="ex-label">이런 식으로 적어도 돼요</p>
33	          <ul className="start__list" aria-labelledby="ex-label">
34	            {EXAMPLES.map((ex) => (
35	              <li key={ex}><button type="button" className="btn btn--ghost btn--sm" onClick={() => { setPrompt(ex); ref.current?.focus(); }}>{ex}</button></li>
36	            ))}
37	          </ul>
38	        </div>
39	        {busy && <div className="notice" role="status"><Clock /><p>첫 질문을 만드는 중이에요. LLM을 쓰면 30초쯤 걸려요.</p></div>}
40	      </div>
41	      <footer className="panel__foot btn-row">
42	        <button type="submit" className="btn btn--primary" disabled={busy} aria-busy={busy}>질문 시작</button>
43	      </footer>
44	    </form>
45	  );
46	}
