235	      if (depth) return q('그 특별한 점을 10초짜리 영상으로 보여 준다면 어떤 장면일까요?', '틱톡에서 손가락을 멈추게 만드는 첫 장면을 떠올려 보세요.', ['처음 보는 조작을 하는 손', '예상 못 한 반전 장면', '친구와 함께 터지는 순간', '점점 커지는 내 세상']);
236	      const combo = chars[0] && places[0] ? `${chars[0]}${josa(chars[0], '과', '와')} ${places[0]}의 의외의 조합` : places.length === 2 ? `${places[0]}${josa(places[0], '과', '와')} ${places[1]}의 의외의 조합` : null;
237	      return q(
238	        `비슷한 게임은 이미 많을 텐데, ${subj}에만 있는 한 가지는 뭔가요?`,
239	        '같은 떡볶이집이라도 그 집에만 있는 메뉴가 하나씩 있잖아요.',
240	        [...(combo ? [combo] : []), '아무도 안 해 본 조작 방식', '할 때마다 바뀌는 세상', '친구의 행동이 내 게임에 영향을 줘요', '짧지만 오래 기억나는 이야기'].slice(0, 5),
241	        true,
242	      );
243	    }
244	  }
