247	/** Restate gate goal line, and the mock concept for the result screen (ELI5: what, analogy, details, so what). */
248	export function goalLine(prompt: string, turns: Turn[]): string {
249	  const role = said(turns, 'role');
250	  const loop = said(turns, 'loop');
251	  if (role && loop) return `${role}${josa(role, '이', '가')} 되어 ${loop}${josa(loop, '을', '를')} 반복하는 게임이에요.`;
252	  if (loop) return `${loop}${josa(loop, '을', '를')} 반복하는 게임이에요.`;
253	  return `“${short(prompt, 60)}”를 바탕으로 한 게임이에요.`;
254	}
