266	export function mockConcept(prompt: string, turns: Turn[]): Concept {
267	  const k = gameKind(prompt, turns);
268	  const { chars, places } = themes(prompt);
269	  const head = [...places.slice(0, 1), ...chars].join(' ') || '나만의';
270	  const fun = said(turns, 'fun');
271	  const loop = said(turns, 'loop');
272	  const audience = said(turns, 'audience');
273	  const platform = said(turns, 'platform');
274	  const unique = said(turns, 'unique');
275	  return {
276	    title: `${head} ${TITLE_TAIL[k]}`,
277	    one_liner: goalLine(prompt, turns),
278	    what: fun && loop ? `한마디로 ${fun}${josa(fun, '으로', '로')} ${loop}${josa(loop, '을', '를')} 계속하는 게임이에요.` : `한마디로 “${short(prompt, 40)}”를 직접 해 보는 게임이에요.`,
279	    analogy: ANALOGY[k],
280	    details: decisions(turns).map((d) => `${d.track}: ${d.decision}`),
281	    so_what: [
282	      audience ? `‘${audience}’도 ${platform ? `‘${platform}’ 동안` : '부담 없이'} 바로 즐길 수 있어요.` : '처음 하는 사람도 바로 알아볼 수 있어요.',
283	      unique ? `‘${unique}’ 덕분에 비슷한 게임 사이에서 기억에 남아요.` : '한 판이 끝나면 다음 판이 궁금해지게 만드는 게 목표예요.',
284	    ].join(' '),
285	  };
286	}
