290	const ELI5_RULES = `Audience: Korean players aged 15-20 (ELI5 "Age 15" + "Senior High/College" styles).
291	- Casual but not cringey, no "fellow kids" energy. Use "-요" polite casual Korean.
292	- Analogies from games, phones, social media, school life.
293	- One idea per sentence. Concrete over abstract.
294	- Any jargon gets a definition inline, e.g. "코어 루프(게임에서 계속 반복하는 행동)".
295	- No emoji, no marketing voice, no invented numbers or facts.`;
296	
297	export const QUESTION_SYSTEM = `You are a Socratic interviewer (ouroboros style) helping a teenager turn a vague game idea into clear decisions. You ONLY ask questions; never promise to build anything.
298	Ambiguity tracks (keys and Korean labels): ${TRACKS.map((t) => `${t.key}=${t.label}`).join(', ')}.
299	Rules for the question:
300	- Exactly ONE question: 1-2 Korean sentences, only ONE question mark, and the text MUST end with "?". No "for example" follow-up question.
301	- No preamble ("좋은 질문이에요", "알겠어요" etc. are banned).
302	- Target the most ambiguous track (the caller suggests one; never use the caller's blocked track).
303	- Build on previous answers; quote a short piece of them when it helps.
304	- Ontological questions are welcome where useful ("이 게임은 결국 무엇을 하는 게임인가요?").
305	- hint: one Korean line with an everyday analogy that makes the question easy to answer.
306	- options: 3-5 short Korean answers (noun phrases, at most about 25 characters, no arrows or symbols), the FIRST one is your recommendation. Do not include "잘 모르겠어요" (the app adds it).
307	- multi: true when several options can be true together.
308	Re-score ambiguity for EVERY track from 0 (fully decided) to 1 (unknown), considering the prompt and all answers so far.
309	${ELI5_RULES}
310	Reply with JSON only: {"track":"<key>","question":"...","hint":"...","options":["..."],"multi":false,"allow_free":true,"ambiguity":{"fun":0.0,...},"done":false}
311	Set "done": true (question may be empty) only when every track is clear enough to write a one-page game concept.`;
312	
313	export function questionUser(prompt: string, turns: Turn[], l: Ledger, target: TrackKey, blocked: TrackKey | null): string {
314	  return JSON.stringify({
315	    prompt,
316	    answered: turns.filter((t) => t.answer).map((t) => ({ track: t.track, question: t.question, answer: decisionOf(t) })),
317	    ambiguity_now: l,
318	    suggested_track: target,
319	    blocked_track: blocked,
320	  });
321	}
322	
323	const str = (v: unknown, max = 300) => (typeof v === 'string' ? v.trim().slice(0, max) : '');
324	
325	/** Validate model output; null means "use the mock instead". */
326	export function parseQuestion(raw: unknown, blocked: TrackKey | null): { q: Question | null; ledger: Partial<Ledger>; done: boolean } {
327	  const r = (raw ?? {}) as Record<string, unknown>;
328	  const ledger: Partial<Ledger> = {};
329	  const amb = (r.ambiguity ?? {}) as Record<string, unknown>;
330	  for (const k of TRACK_KEYS) if (typeof amb[k] === 'number' && Number.isFinite(amb[k])) ledger[k] = clamp(amb[k] as number);
331	  const done = r.done === true;
332	  const track = r.track as TrackKey;
333	  const question = str(r.question);
334	  const options = Array.isArray(r.options) ? [...new Set(r.options.map((o) => str(o, 80)).filter((o) => o && o !== RECOMMEND))].slice(0, 5) : [];
335	  const ok = TRACK_KEYS.includes(track) && track !== blocked && /[?？]$/.test(question) && options.length >= 2;
336	  return { q: ok ? { track, question, hint: str(r.hint, 200), options, multi: r.multi === true, allow_free: r.allow_free !== false } : null, ledger, done };
337	}
