339	export const CONCEPT_SYSTEM = `You turn a finished game-idea interview into a short ELI5 concept card in Korean.
340	${ELI5_RULES}
341	Structure (ELI5): start with the "what" in one sentence, then an analogy, then details, then the "so what".
342	Reply with JSON only:
343	{"title":"게임 이름(가제), 2-12 Korean chars, catchy but plain","one_liner":"one sentence","what":"이게 뭐냐면: one sentence","analogy":"비유하자면: 1-2 sentences","details":["3-6 short bullets"],"so_what":"그래서 왜 재밌냐면: 1-2 sentences"}
344	Do not start values with the section names ("이게 뭐냐면:", "비유하자면:" ...); the app shows them as headings.
345	Use only what the prompt and answers say; do not invent features, numbers or facts.`;
346	
347	export function conceptUser(prompt: string, turns: Turn[]): string {
348	  return JSON.stringify({ prompt, decisions: decisions(turns).map(({ track, decision }) => ({ track, decision })) });
349	}
350	
351	const LABEL = /^(이게 뭐냐면|비유하자면|조금 더 자세히|그래서 왜 재밌냐면)\s*[:：]\s*/;
352	export function parseConcept(raw: unknown, fallback: Concept): Concept {
353	  const r = (raw ?? {}) as Record<string, unknown>;
354	  const str = (v: unknown, max = 300) => (typeof v === 'string' ? v.trim().replace(LABEL, '').slice(0, max) : '');
355	  const details = Array.isArray(r.details) ? r.details.map((d) => str(d, 200)).filter(Boolean).slice(0, 8) : [];
356	  return {
357	    title: str(r.title, 40) || fallback.title,
358	    one_liner: str(r.one_liner) || fallback.one_liner,
359	    what: str(r.what) || fallback.what,
360	    analogy: str(r.analogy) || fallback.analogy,
361	    details: details.length ? details : fallback.details,
362	    so_what: str(r.so_what) || fallback.so_what,
363	  };
364	}
