 39	export function getState(id: string): State | null {
 40	  const x = rows(id);
 41	  if (!x) return null;
 42	  const { s, t, ledger } = x;
 43	  const views: TurnView[] = t.map((r) => ({
 44	    id: r.id, idx: r.idx, track: r.track, trackLabel: label(r.track), question: r.question, hint: r.hint ?? '',
 45	    options: JSON.parse(r.options), multi: !!r.multi, allowFree: !!r.allow_free, answer: r.answer ? JSON.parse(r.answer) : null, provider: r.provider ?? '',
 46	  }));
 47	  const open = views.find((v) => !v.answer) ?? null;
 48	  const turns = t.map(toTurn);
 49	  const res = db().prepare('SELECT * FROM step1_results WHERE session_id = ?').get(id) as { title: string; one_liner: string; concept: string; provider: string | null } | undefined;
 50	  const ledgerView = TRACKS.map((tr) => ({ key: tr.key, label: tr.label, score: ledger[tr.key] ?? 1, clear: (ledger[tr.key] ?? 1) <= CLEAR }));
 51	  return {
 52	    id: s.id, prompt: s.prompt, status: s.status, createdAt: s.created_at,
 53	    overall: overall(ledger), ledger: ledgerView, turns: views, open,
 54	    restate: s.status === 'interviewing' && !open
 55	      ? { goal: goalLine(s.prompt, turns), decisions: decisions(turns).map(({ track, decision }) => ({ track, decision })), fuzzy: ledgerView.filter((l) => !l.clear).map((l) => l.label), canAskMore: t.length < HARD_CAP }
 56	      : null,
 57	    result: res ? { title: res.title, one_liner: res.one_liner, concept: JSON.parse(res.concept), provider: res.provider ?? '' } : null,
