 32	const SAMPLE_PROMPT = '고양이가 우주 농장을 운영하는 느긋한 게임';
 33	const SAMPLE: Record<TrackKey, Answer> = {
 34	  fun: { choices: ['차곡차곡 키우고 꾸미는 재미'], text: '행성마다 다른 작물이 자라는 걸 보는 맛' },
