 36	  role: { choices: ['고양이 본인(직접 조종)'], text: '' },
 37	  win: { choices: ['끝이 없고 계속 성장만 해요'], text: '대신 주간 목표가 있어요' },
 38	  mood: { choices: ['말랑하고 귀여운 파스텔'], text: '' },
 39	  unique: { choices: [], text: '친구 우주 농장에 놀러 가서 작물을 몰래 가져오기' },
