 44	function seed() {
 45	  const d = db();
 46	  if (d.prepare('SELECT 1 FROM step1_sessions LIMIT 1').get()) return;
 47	  const now = new Date().toISOString();
 48	  let ledger = initialLedger(SAMPLE_PROMPT);
 49	  const turns: Turn[] = [];
 50	  const ins = d.prepare('INSERT INTO step1_turns (id, session_id, idx, track, question, hint, options, allow_free, multi, answer, ledger, provider, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, 1, ?, ?, ?, ?, ?)');
 51	  d.exec('BEGIN');
 52	  try {
 53	    for (let i = 0; !shouldStop(ledger, i); i++) {
 54	      const q = mockQuestion(SAMPLE_PROMPT, turns, pickTrack(ledger, turns.map((t) => t.track)));
 55	      const a = SAMPLE[q.track];
 56	      ins.run(`sample-${i}`, 'sample', i, q.track, q.question, q.hint, JSON.stringify(q.options), q.multi ? 1 : 0, JSON.stringify(a), JSON.stringify(ledger), 'seed', now);
 57	      turns.push({ track: q.track, question: q.question, options: q.options, answer: a });
 58	      ledger = applyAnswer(ledger, q.track, a);
 59	    }
 60	    const c = mockConcept(SAMPLE_PROMPT, turns);
 61	    d.prepare('INSERT INTO step1_sessions (id, prompt, status, ambiguity, tracks, created_at) VALUES (?, ?, ?, ?, ?, ?)').run('sample', SAMPLE_PROMPT, 'done', overall(ledger), JSON.stringify(ledger), now);
 62	    d.prepare('INSERT INTO step1_results (session_id, title, one_liner, concept, provider, created_at) VALUES (?, ?, ?, ?, ?, ?)').run(
 63	      'sample', c.title, c.one_liner,
 64	      JSON.stringify({ what: c.what, analogy: c.analogy, details: c.details, so_what: c.so_what, decisions: decisions(turns).map(({ track, decision }) => ({ track, decision })) }),
 65	      'seed', now,
 66	    );
 67	    d.exec('COMMIT');
 68	  } catch (e) {
 69	    d.exec('ROLLBACK');
 70	    throw e;
 71	  }
 72	}

