     1	import Anthropic from '@anthropic-ai/sdk';
     2	import { execFile } from 'node:child_process';
     3	
     4	// Provider order: ANTHROPIC_API_KEY → local `claude` CLI (uses the logged-in Claude Code) → deterministic mock.
     5	// Force one with LLM_PROVIDER=anthropic|claude-cli|mock.
     6	export type Provider = 'anthropic' | 'claude-cli' | 'mock';
     7	
     8	export function provider(): Provider {
     9	  const forced = process.env.LLM_PROVIDER as Provider | undefined;
    10	  if (forced) return forced;
    11	  if (process.env.ANTHROPIC_API_KEY) return 'anthropic';
    12	  if (process.env.LLM_DISABLE_CLI !== '1') return 'claude-cli';
    13	  return 'mock';
    14	}
    15	
    16	function extractJSON(text: string): unknown {
    17	  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/);
    18	  const body = fenced ? fenced[1] : text;
    19	  const start = body.search(/[[{]/);
    20	  if (start < 0) throw new Error('no JSON in model output');
    21	  const end = Math.max(body.lastIndexOf('}'), body.lastIndexOf(']'));
    22	  return JSON.parse(body.slice(start, end + 1));
    23	}
    24	
    25	async function viaAnthropic(system: string, user: string): Promise<string> {
    26	  const client = new Anthropic();
    27	  const res = await client.messages.create({
    28	    model: process.env.LLM_MODEL ?? 'claude-sonnet-5-5',
    29	    max_tokens: 4096,
    30	    system,
    31	    messages: [{ role: 'user', content: user }],
    32	  });
    33	  return res.content.map((b) => (b.type === 'text' ? b.text : '')).join('');
    34	}
    35	
    36	function viaClaudeCli(system: string, user: string): Promise<string> {
    37	  const env = { ...process.env };
    38	  delete env.CLAUDECODE; // allow running from inside a Claude Code session
    39	  return new Promise((resolve, reject) => {
    40	    execFile(
    41	      'claude',
    42	      ['-p', user, '--append-system-prompt', system, '--output-format', 'json', '--model', process.env.LLM_CLI_MODEL ?? 'sonnet'],
    43	      { env, timeout: Number(process.env.LLM_TIMEOUT_MS ?? 120000), maxBuffer: 10 * 1024 * 1024 },
    44	      (err, stdout) => {
    45	        if (err) return reject(err);
    46	        try {
    47	          resolve(String((JSON.parse(stdout) as { result?: string }).result ?? ''));
    48	        } catch (e) {
    49	          reject(e);
    50	        }
    51	      },
    52	    );
    53	  });
    54	}
    55	
    56	/** Ask the model for JSON. Any failure falls back to `fallback()` so the PoC always works offline. */
    57	export async function completeJSON<T>(
    58	  system: string,
    59	  user: string,
    60	  fallback: () => T,
    61	): Promise<{ data: T; provider: Provider; error?: string }> {
    62	  const p = provider();
    63	  if (p === 'mock') return { data: fallback(), provider: 'mock' };
    64	  try {
    65	    const text = p === 'anthropic' ? await viaAnthropic(system, user) : await viaClaudeCli(system, user);
    66	    return { data: extractJSON(text) as T, provider: p };
    67	  } catch (e) {
    68	    return { data: fallback(), provider: 'mock', error: `${p} failed: ${(e as Error).message.slice(0, 200)}` };
    69	  }
    70	}
